-- post: routine-du-soir-en-quatre-gestes (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10026, now(), now(), 'seed', 'routine-du-soir-en-quatre-gestes', 'POST', 0, true, '65f020632bc46470c104b76f', 'PUBLISHED', now() - interval '3 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -190003, "categoryIds": [-151], "tags": ["routine", "soir", "peau sèche"], "authorName": "Claire Bouvier", "featured": true}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100051, now(), now(), 'seed', '<p>La peau ne se répare pas la nuit par magie : elle le fait parce que la barrière cutanée est enfin débarrassée de ce qui l''encombre. D''où quatre gestes, pas douze.</p><h2>1. Démaquiller à l''huile</h2><p>Une huile démaquillante dissout le maquillage, le sébum et les filtres solaires, que l''eau seule ne délogera jamais. Massez deux minutes sur peau sèche, puis émulsionnez.</p><h2>2. Nettoyer en douceur</h2><p>Un gel sans sulfates, à pH 5,5. La peau doit être souple après rinçage, jamais tiraillée : le tiraillement est le signe d''un nettoyant trop décapant.</p><h2>3. Traiter</h2><p>Un seul actif par soir. Le rétinal le lundi et le jeudi, l''acide lactique le mercredi, rien les autres jours. Empiler les actifs abîme la barrière plus vite qu''il ne corrige quoi que ce soit.</p><h2>4. Sceller</h2><p>Une crème plus riche que celle du matin, avec des céramides. Elle limite la perte insensible en eau, qui culmine entre 23h et 4h.</p><p>Quatre semaines suffisent pour juger. Avant, vous ne mesurez que la lumière de votre salle de bains.</p>', 'La routine du soir en quatre gestes', 'La routine du soir en quatre gestes', 'Démaquillage à l''huile, nettoyant doux, actif ciblé, crème occlusive : la routine du soir expliquée geste par geste.', 'routine, soir, peau sèche', 'La routine du soir en quatre gestes | Le Journal', 'routine-du-soir-en-quatre-gestes', 'fr', -10026, 'TRANSLATED', 'Démaquiller, nettoyer, traiter, sceller : quatre gestes suffisent, à condition de les faire dans cet ordre.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100052, now(), now(), 'seed', '<p>Skin does not repair itself overnight by magic. It does it because the barrier is finally free of what was sitting on it. Hence four steps, not twelve.</p><h2>1. Take it off with oil</h2><p>A cleansing oil dissolves make-up, sebum and sunscreen filters that water alone will never shift. Massage for two minutes on dry skin, then emulsify.</p><h2>2. Cleanse gently</h2><p>A sulfate-free gel at pH 5.5. Skin should feel supple after rinsing, never tight: tightness is the sign of a cleanser that has stripped it.</p><h2>3. Treat</h2><p>One active per evening. Retinal on Monday and Thursday, lactic acid on Wednesday, nothing the rest of the week. Stacking actives damages the barrier faster than it corrects anything.</p><h2>4. Seal</h2><p>A richer cream than the morning one, with ceramides. It limits transepidermal water loss, which peaks between 11pm and 4am.</p><p>Four weeks is enough to judge. Before that, all you are measuring is your bathroom lighting.</p>', 'The evening routine in four steps', 'The evening routine in four steps', 'Oil cleansing, a gentle wash, one targeted active, an occlusive cream: the evening routine, step by step.', 'routine, soir, peau sèche', 'The evening routine in four steps | The Journal', 'the-evening-routine-in-four-steps', 'en', -10026, 'TRANSLATED', 'Remove, cleanse, treat, seal: four steps are enough, provided you do them in that order.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-1001, -190003, 'CONTENT', '-10026', 'La routine du soir en quatre gestes', -10026, 'POST', 'hero')
