-- post: niacinamide-ce-quelle-fait-vraiment (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10027, now(), now(), 'seed', 'niacinamide-ce-quelle-fait-vraiment', 'POST', 1, true, '65f020632bc46470c104b76f', 'PUBLISHED', now() - interval '9 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -190004, "categoryIds": [-152], "tags": ["niacinamide", "actifs"], "authorName": "Dr. Amina Roussel", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100053, now(), now(), 'seed', '<p>La niacinamide, ou vitamine B3, est l''actif le plus consensuel de la cosmétique — ce qui explique qu''on la trouve partout, y compris là où elle ne sert à rien.</p><h2>Ce qui est documenté</h2><ul><li>Réduction de la production de sébum à partir de 2 %</li><li>Éclaircissement des taches post-inflammatoires à 4–5 %, sur douze semaines</li><li>Renforcement de la barrière lipidique par stimulation des céramides</li></ul><h2>Le mythe des 20 %</h2><p>Au-delà de 10 %, les études ne montrent aucun bénéfice supplémentaire, mais une nette hausse des rougeurs et des picotements. Nos sérums s''arrêtent à 5 %.</p><h2>Avec quoi l''associer</h2><p>Avec à peu près tout, y compris la vitamine C : l''incompatibilité rapportée date d''expériences menées à 60 °C, pas sur un visage.</p>', 'Niacinamide : ce qu''elle fait vraiment', 'Niacinamide : ce qu''elle fait vraiment', 'Ce que la littérature dit de la niacinamide : sébum, taches pigmentaires, barrière cutanée, et le pourcentage utile.', 'niacinamide, actifs', 'Niacinamide : ce qu''elle fait vraiment | Le Journal', 'niacinamide-ce-quelle-fait-vraiment', 'fr', -10027, 'TRANSLATED', 'À 5 %, la niacinamide régule le sébum et éclaircit les taches. À 20 %, elle irrite. La dose fait tout.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100054, now(), now(), 'seed', '<p>Niacinamide, or vitamin B3, is the least contested active in cosmetics — which is why it turns up everywhere, including where it does nothing.</p><h2>What is documented</h2><ul><li>Lower sebum production from 2% upward</li><li>Fading of post-inflammatory marks at 4–5%, over twelve weeks</li><li>A stronger lipid barrier through ceramide synthesis</li></ul><h2>The 20% myth</h2><p>Above 10%, studies show no further benefit but a clear rise in redness and stinging. Our serums stop at 5%.</p><h2>What to pair it with</h2><p>Almost anything, vitamin C included: the incompatibility people repeat comes from experiments run at 60°C, not on a face.</p>', 'Niacinamide: what it actually does', 'Niacinamide: what it actually does', 'What the literature says about niacinamide: sebum, pigmentation, barrier function, and the percentage that is useful.', 'niacinamide, actifs', 'Niacinamide: what it actually does | The Journal', 'niacinamide-what-it-actually-does', 'en', -10027, 'TRANSLATED', 'At 5%, niacinamide regulates sebum and fades marks. At 20%, it irritates. The dose is the whole story.', null, null, null)
on conflict (description_id) do nothing;
