-- post: dans-latelier-de-nantes (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10028, now(), now(), 'seed', 'dans-latelier-de-nantes', 'POST', 2, true, '65f020632bc46470c104b76f', 'PUBLISHED', now() - interval '18 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -190005, "categoryIds": [-153], "tags": ["atelier", "fabrication"], "authorName": "Claire Bouvier", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100055, now(), now(), 'seed', '<p>L''atelier tient dans quatre cents mètres carrés d''une ancienne imprimerie. Trois cuves inox, une salle de pesée sous flux, et Marion, qui formule depuis onze ans.</p><h2>Un lot, une journée</h2><p>Une émulsion demande six heures : chauffe des phases à 75 °C, homogénéisation, refroidissement lent sous agitation, puis ajout des actifs thermosensibles sous les 40 °C.</p><h2>Le contrôle qui coûte cher</h2><p>Chaque lot part en challenge test microbiologique pendant vingt-huit jours avant expédition. C''est long, c''est cher, et c''est ce qui nous permet de ne pas surcharger les formules en conservateurs.</p>', 'Dans l''atelier de Nantes', 'Dans l''atelier de Nantes', 'Reportage dans l''atelier où sont fabriquées les émulsions Beauté Élégante.', 'atelier, fabrication', 'Dans l''atelier de Nantes | Le Journal', 'dans-latelier-de-nantes', 'fr', -10028, 'TRANSLATED', 'Six cents litres par semaine, trois cuves, une chimiste et beaucoup de nettoyage entre deux lots.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100056, now(), now(), 'seed', '<p>The workshop fits into four hundred square metres of a former print house. Three stainless vessels, a weighing room under laminar flow, and Marion, who has been formulating for eleven years.</p><h2>One batch, one day</h2><p>An emulsion takes six hours: phases heated to 75°C, homogenised, cooled slowly under agitation, then the heat-sensitive actives added below 40°C.</p><h2>The expensive control</h2><p>Every batch goes through a twenty-eight-day microbiological challenge test before it ships. It is slow and it is costly, and it is what lets us keep the preservative load low.</p>', 'Inside the Nantes workshop', 'Inside the Nantes workshop', 'A visit to the workshop where the Beauté Élégante emulsions are made.', 'atelier, fabrication', 'Inside the Nantes workshop | The Journal', 'inside-the-nantes-workshop', 'en', -10028, 'TRANSLATED', 'Six hundred litres a week, three vessels, one chemist, and a great deal of cleaning between batches.', null, null, null)
on conflict (description_id) do nothing;
