-- post: choisir-son-spf (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10029, now(), now(), 'seed', 'choisir-son-spf', 'POST', 3, true, '65f020632bc46470c104b76f', 'PUBLISHED', now() - interval '27 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -190006, "categoryIds": [-151, -152], "tags": ["spf", "protection solaire", "routine"], "authorName": "Dr. Amina Roussel", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100057, now(), now(), 'seed', '<h2>La quantité d''abord</h2><p>L''indice est mesuré à 2 mg/cm², soit environ une cuillère à café pour le visage et le cou. Presque personne n''en met autant : un SPF 50 appliqué au tiers protège comme un SPF 15.</p><h2>Minéral ou organique ?</h2><p>Les filtres minéraux (oxyde de zinc, dioxyde de titane) conviennent aux peaux réactives mais laissent un voile blanc. Les filtres organiques modernes sont photostables et invisibles. Les deux protègent.</p><h2>Renouveler</h2><p>Toutes les deux heures en extérieur, après chaque baignade. En intérieur derrière une fenêtre, une application le matin suffit.</p>', 'Choisir son SPF sans se tromper', 'Choisir son SPF sans se tromper', 'Indice, quantité, filtres minéraux ou organiques, renouvellement : comment choisir et appliquer une protection solaire.', 'spf, protection solaire, routine', 'Choisir son SPF sans se tromper | Le Journal', 'choisir-son-spf', 'fr', -10029, 'TRANSLATED', 'SPF 30 appliqué correctement bat SPF 50 appliqué à moitié. La quantité compte plus que l''indice.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100058, now(), now(), 'seed', '<h2>Quantity first</h2><p>The factor is measured at 2 mg/cm², roughly a teaspoon for face and neck. Almost nobody applies that much: an SPF 50 laid on at a third of the dose protects like an SPF 15.</p><h2>Mineral or organic?</h2><p>Mineral filters (zinc oxide, titanium dioxide) suit reactive skin but leave a white cast. Modern organic filters are photostable and invisible. Both protect.</p><h2>Reapply</h2><p>Every two hours outdoors, and after every swim. Indoors behind a window, one morning application is enough.</p>', 'Choosing an SPF without getting it wrong', 'Choosing an SPF without getting it wrong', 'Factor, quantity, mineral or organic filters, reapplication: how to choose and use a sunscreen.', 'spf, protection solaire, routine', 'Choosing an SPF without getting it wrong | The Journal', 'choosing-an-spf', 'en', -10029, 'TRANSLATED', 'SPF 30 applied properly beats SPF 50 applied by half. Quantity matters more than the number.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-1004, -190006, 'CONTENT', '-10029', 'Choisir son SPF sans se tromper', -10029, 'POST', 'hero')
