-- post: peau-mixte-en-hiver (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10030, now(), now(), 'seed', 'peau-mixte-en-hiver', 'POST', 4, true, '65f020632bc46470c104b76f', 'PUBLISHED', now() - interval '41 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -190007, "categoryIds": [-151], "tags": ["peau mixte", "hiver", "routine"], "authorName": "Marion Lefèvre", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100059, now(), now(), 'seed', '<p>Le froid ne rend pas la peau mixte plus sèche partout : il assèche les joues pendant que la zone T continue son travail.</p><h2>Deux textures, un visage</h2><p>Rien n''interdit d''appliquer un fluide léger sur la zone T et une crème riche sur les joues. C''est même la seule réponse sensée.</p><h2>Baisser la fréquence, pas la dose</h2><p>Passez vos exfoliants de trois fois à une fois par semaine plutôt que de diluer le produit. La peau supporte mieux un geste fort espacé qu''un geste faible quotidien.</p><h2>Le nettoyage du matin</h2><p>À l''eau tiède seule, si la peau tiraille. Le nettoyant du soir a déjà fait le travail.</p>', 'Peau mixte en hiver : arrêter de sur-traiter', 'Peau mixte en hiver : arrêter de sur-traiter', 'Comment adapter une routine peau mixte au froid sans assécher les joues ni relancer la zone T.', 'peau mixte, hiver, routine', 'Peau mixte en hiver | Le Journal', 'peau-mixte-en-hiver', 'fr', -10030, 'TRANSLATED', 'La zone T brille, les joues tirent, et la réponse habituelle — décaper partout — aggrave les deux.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100060, now(), now(), 'seed', '<p>Cold weather does not make combination skin uniformly dry: it dries the cheeks while the T-zone carries on as before.</p><h2>Two textures, one face</h2><p>Nothing stops you putting a light fluid on the T-zone and a rich cream on the cheeks. It is in fact the only sensible answer.</p><h2>Lower the frequency, not the dose</h2><p>Take exfoliants from three times a week to once, rather than diluting the product. Skin tolerates a strong step spaced out better than a weak step every day.</p><h2>The morning cleanse</h2><p>Lukewarm water alone, if skin feels tight. The evening cleanser already did the work.</p>', 'Combination skin in winter: stop over-treating', 'Combination skin in winter: stop over-treating', 'How to adapt a combination-skin routine to the cold without drying the cheeks or provoking the T-zone.', 'peau mixte, hiver, routine', 'Combination skin in winter | The Journal', 'combination-skin-in-winter', 'en', -10030, 'TRANSLATED', 'The T-zone shines, the cheeks feel tight, and the usual answer — stripping everything — makes both worse.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-1005, -190007, 'CONTENT', '-10030', 'Peau mixte en hiver : arrêter de sur-traiter', -10030, 'POST', 'hero')
on conflict (id) do nothing;

-- post: le-verre-consigne (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10031, now(), now(), 'seed', 'le-verre-consigne', 'POST', 5, true, '65f020632bc46470c104b76f', 'PUBLISHED', now() - interval '60 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -190003, "categoryIds": [-153], "tags": ["durable", "recharge"], "authorName": "Claire Bouvier", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100061, now(), now(), 'seed', '<p>Recycler du verre veut dire le fondre à 1 500 °C. Le relaver demande de l''eau chaude à 80 °C. L''écart d''énergie est d''un facteur quatre environ.</p><h2>Le circuit</h2><p>Vous rapportez le flacon en boutique, nous vous rendons trois euros, le flacon part au laveur de Rezé et revient dans le circuit sous trois semaines.</p><h2>La limite</h2><p>Cela ne marche qu''en boutique : renvoyer un flacon vide par la poste annulerait le gain. C''est la raison pour laquelle la consigne n''existe pas en ligne.</p>', 'Pourquoi nous consignons le verre', 'Pourquoi nous consignons le verre', 'Le bilan carbone comparé du verre recyclé et du verre consigné, et ce que cela change en boutique.', 'durable, recharge', 'Pourquoi nous consignons le verre | Le Journal', 'le-verre-consigne', 'fr', -10031, 'TRANSLATED', 'Un flacon rapporté et relavé pèse quatre fois moins qu''un flacon recyclé. Le calcul nous a surpris.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100062, now(), now(), 'seed', '<p>Recycling glass means melting it at 1,500°C. Rewashing it needs hot water at 80°C. The energy gap is roughly a factor of four.</p><h2>The loop</h2><p>You bring the bottle back to the boutique, we hand you three euros, the bottle goes to the washer in Rezé and is back in circulation within three weeks.</p><h2>The catch</h2><p>It only works in the boutique: posting an empty bottle back would cancel the gain. That is why there is no deposit online.</p>', 'Why we put a deposit on glass', 'Why we put a deposit on glass', 'The comparative carbon cost of recycled and returnable glass, and what it changes in the boutique.', 'durable, recharge', 'Why we put a deposit on glass | The Journal', 'why-we-put-a-deposit-on-glass', 'en', -10031, 'TRANSLATED', 'A bottle brought back and rewashed costs about a quarter of what recycling it does. The maths surprised us.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-1006, -190003, 'CONTENT', '-10031', 'Pourquoi nous consignons le verre', -10031, 'POST', 'hero')
